1	// Splices climb batch 8's MANIFEST block into a scratch copy of the workflow script and checks it, in the form of
2	// explorations/compile-ladder/plan-7b/manifest/check7b.js: node --check on the original and the spliced copy; the
3	// spliced copy parsed as the body of an async function, as the Workflow harness parses it (FACTS, "node --check does
4	// not check the batch script as the Workflow harness parses it ..."); every line outside the block byte-identical;
5	// the launch value refused when unset; the rungs, their order, the scatter and the entries' fields; each tail equal to
6	// its rung's section of the record followed by its briefing's reasons, one per key in order; no backtick or non-ASCII
7	// character in any string the agents read; each checks list a sub-list of its briefing; no tail or intro asking for a
8	// test citation to be re-anchored (the rule went at 2040cd056); the record's section 7 holds no copy of the block. Its
9	// last line counts the problems. Reads $OUT8/manifest8.js (gen8.py's output) and writes the spliced copy beside it.
10	//   node check8.js [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-8.md
11	const fs = require('fs')
12	const cp = require('child_process')
13	const path = require('path')
14	const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
15	const HERE = process.env.OUT8 || path.join(ROOT, 'tmp')
16	const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
17	const REC = process.argv[2] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-8.md')
18	const block = fs.readFileSync(path.join(HERE, 'manifest8.js'), 'utf8')
19	const orig = fs.readFileSync(SRC, 'utf8')
20	const lines = orig.split('\n')
21	const mIdx = lines.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
22	const start = mIdx - 1
23	if (!/^\/\/ =+$/.test(lines[start])) throw new Error('no rule above MANIFEST')
24	const end = lines.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
25	console.log('original script: MANIFEST block is lines', start + 1, 'to', end, 'of', lines.length)
26	const pre = lines.slice(0, start).join('\n'), post = lines.slice(end).join('\n')
27	const spliced = pre + '\n' + block + post
28	const out = path.join(HERE, 'wf-spliced-8.js')
29	fs.writeFileSync(out, spliced)
30	let bad = 0
31	if (!spliced.startsWith(pre + '\n') || !spliced.endsWith(post)) { bad++; console.log('outside the block differs') }
32	for (const f of [SRC, out]) {
33	  const r = cp.spawnSync('node', ['--check', f], { encoding: 'utf8' })
34	  console.log('node --check', path.basename(f), 'exit', r.status, r.stderr.trim().slice(0, 300))
35	  if (r.status !== 0) bad++
36	}
37	const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
38	for (const [name, text] of [['original', orig], ['spliced', spliced]]) {
39	  // the harness takes the script's one export (export const meta) out before it runs the rest as a function body
40	  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', text.replace(/^export const meta/m, 'const meta')); console.log('parses as an async function body, its export taken out:', name) }
41	  catch (e) { bad++; console.log('does NOT parse as an async function body:', name, e.message) }
42	}
43	// the manifest part, evaluated with the script's own key validation and scatter order
44	const sl = spliced.split('\n')
45	const s2 = sl.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces')) - 1
46	const e2 = sl.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
47	const manifest = sl.slice(s2, e2).join('\n')
48	const valStart = sl.findIndex(l => l.startsWith('const LOOKUP_TOOL = '))
49	const valEnd = sl.findIndex(l => l.startsWith('const keysOf = '))
50	const validation = sl.slice(valStart, valEnd + 1).join('\n')
51	const scatterLine = sl.find(l => l.startsWith('const SCATTER = '))
52	function evalWith(ledger) {
53	  let m = manifest
54	  if (ledger !== null) m = m.replace(/^const LEDGER_FROM = null/m, 'const LEDGER_FROM = ' + ledger)
55	  const f = new Function(m + '\n' + validation + '\n' + scatterLine + '\nreturn { BATCH, BATCH_RECORD, RUNGS, SCATTER, BATCH_INTRO, BATCH_OVERLAPS, LEDGER_FROM }')
56	  return f()
57	}
58	try { evalWith(null); bad++; console.log('LEDGER_FROM unset: did NOT throw (bad)') } catch (e) { console.log('LEDGER_FROM unset: throws:', e.message) }
59	const REASONS_HEAD = '**Your briefing, entry by entry.**'
60	const rec = fs.readFileSync(REC, 'utf8')
61	const s3 = rec.slice(rec.indexOf('\n## 3. The rungs\n'), rec.indexOf('\n## 4. '))
62	function section(id) {
63	  const re = new RegExp('^### ' + id + '\\. .*$', 'm')
64	  const m = re.exec(s3); if (!m) throw new Error('no section ' + id)
65	  const rest = s3.slice(m.index + m[0].length)
66	  const nx = rest.search(/^### [A-Z]\. /m)
67	  return (nx < 0 ? rest : rest.slice(0, nx)).replace(/^\n+|\n+$/g, '').replace(/`/g, '')
68	}
69	const r = evalWith(559)
70	const ids = r.RUNGS.map(x => x.id).join(', ')
71	const stage = r.RUNGS.filter(x => x.testIsStage).map(x => x.id).join(', ')
72	console.log('batch ' + r.BATCH + ', rungs ' + ids + ', scatter ' + r.SCATTER.map(x => x.id).join(', ') + ', testIsStage ' + stage + ', LEDGER_FROM ' + r.LEDGER_FROM + ', intro ' + r.BATCH_INTRO.length + ' chars, overlaps ' + r.BATCH_OVERLAPS.length + ' chars')
73	if (r.BATCH !== '8' || ids !== 'I, O, Q, M' || r.SCATTER.map(x => x.id).join('') !== 'IQOM' || stage !== 'M') { bad++; console.log('  batch, rungs, scatter or testIsStage not as the record says') }
74	if (r.RUNGS.some(x => x.expectedCheckerCount !== undefined || x.expectedCheckerCrash !== undefined || x.landsOnlyWith)) { bad++; console.log('  a rung declares a count, a crash or landsOnlyWith, which the record does not') }
75	const reanchor = /re-anchor/i
76	for (const x of r.RUNGS) {
77	  const tl = x.tail.split('\n')
78	  const rh = tl.findIndex(l => l.startsWith(REASONS_HEAD))
79	  if (rh < 0) { bad++; console.log('  tail ' + x.id + ' has no reasons block'); continue }
80	  const body = tl.slice(7, rh - 1).join('\n')
81	  const want = section(x.id)
82	  if (body !== want || tl[rh - 1] !== '') { bad++; console.log('  tail ' + x.id + ' differs from its section') }
83	  const reasons = tl.slice(rh + 1, tl.length - 1)
84	  const keys = x.briefing || []
85	  if (reasons.length !== keys.length || !keys.every((k, i) => reasons[i].startsWith('- ' + k + ': ') && reasons[i].length > k.length + 6)) { bad++; console.log('  tail ' + x.id + ': the reasons are not one line per briefing key, in order') }
86	  if (tl[tl.length - 1] !== '') { bad++; console.log('  tail ' + x.id + ' does not end with an empty line') }
87	  for (const [name, text] of [['tail ' + x.id, x.tail], ['blurb ' + x.id, x.blurb]]) {
88	    if (/[^\x00-\x7f]/.test(text) || /`/.test(text)) { bad++; console.log('  ' + name + ' holds a backtick or non-ASCII') }
89	    if (reanchor.test(text)) { bad++; console.log('  ' + name + ' asks for a re-anchoring') }
90	  }
91	  if (!(x.checks || []).every(k => x.briefing.includes(k))) { bad++; console.log('  checks not a sub-list: ' + x.id) }
92	  if (!x.path || !x.branch || x.branch !== 'wip/' + x.slug) { bad++; console.log('  ' + x.id + ': path or branch missing, or the branch is not wip/<slug>') }
93	  console.log('  ' + x.id + ': tail ' + tl.length + ' lines, briefing ' + keys.length + ' keys, checks ' + (x.checks || []).length + ' keys, ' + x.path + ' on ' + x.branch)
94	}
95	for (const [name, text] of [['intro', r.BATCH_INTRO], ['overlaps', r.BATCH_OVERLAPS]]) {
96	  if (/[^\x00-\x7f]/.test(text) || /`/.test(text)) { bad++; console.log('  ' + name + ' holds a backtick or non-ASCII') }
97	  if (reanchor.test(text)) { bad++; console.log('  ' + name + ' asks for a re-anchoring') }
98	}
99	// the record's section 7 names the generator and holds no copy of the block
100	const i7 = rec.indexOf('\n## 7. The manifest\n'), e7 = rec.indexOf('\n## 8. ', i7)
101	const s7 = i7 < 0 || e7 < 0 ? '' : rec.slice(i7, e7)
102	if (!s7 || s7.includes('```') || s7.includes('const RUNGS') || !s7.includes('gen8.py')) { bad++; console.log('the record\'s section 7 is not the one sentence naming gen8.py, or holds a copy of the block') }
103	else console.log('the record\'s section 7 names gen8.py and holds no copy of the block')
104	console.log('problems:', bad)
